583	function validateContactForm(value: ContactFormInput): { fields: ContactFormErrors } | undefined {
584		const result = contactFormSchema.safeParse(normalizeFormValues(value));
585		if (result.success) {
586			return undefined;
587		}
588	
589		const fields: ContactFormErrors = {};
590		for (const issue of result.error.issues) {
591			const field = issue.path[0];
592			if (typeof field === 'string' && field in initialFormData && !fields[field as keyof ContactFormInput]) {
593				fields[field as keyof ContactFormInput] = issue.message;
594			}
595		}
596		if (!value.email.trim()) {
