1334	interface HeroSectionProps {
1335		title?: string | null;
1336		subTitle?: string | null;
1337	}
1338	
1339	const emojiRegex = /(\p{Emoji_Presentation}|\p{Extended_Pictographic})/gu;
1340	// Stega encoding inserts zero-width characters (\u200b, \u200c, \u200d, \ufeff) throughout text
1341	const stegaChars = '\u200b\u200c\u200d\ufeff';
1342	
1343	/** Splits trailing emojis from the subtitle so they can be styled separately on mobile. */
1344	function splitTrailingEmojis(text: string) {
1345		// Strip Stega zero-width chars for matching, but find the split point in the original
1346		const clean = text.replace(new RegExp(`[${stegaChars}]`, 'g'), '').trimEnd();
1347		const match = clean.match(/[\s\p{Emoji_Presentation}\p{Extended_Pictographic}]+$/u);
1348		if (!match) return { text, emojis: '' };
1349		const emojis = match[0].match(emojiRegex);
1350		if (!emojis) return { text, emojis: '' };
1351		const cleanTextPart = clean.slice(0, match.index).trimEnd();
1352		// Find the position in the original string that corresponds to the end of cleanTextPart
1353		let cleanIdx = 0;
1354		let origIdx = 0;
1355		while (cleanIdx < cleanTextPart.length && origIdx < text.length) {
1356			if (stegaChars.includes(text[origIdx])) {
1357				origIdx++;
1358			} else {
1359				cleanIdx++;
1360				origIdx++;
1361			}
1362		}
1363		return {
1364			text: text.slice(0, origIdx),
1365			emojis: emojis.join(' '),
1366		};
1367	}
1368	
1369	export function HeroSection({ title, subTitle }: HeroSectionProps) {
1370		const parts = subTitle ? splitTrailingEmojis(subTitle) : null;
1371	
1372		return (
1373			<section className={heroSection}>
1374				<div className={heroContent}>
1375					<h1 className={heroTitle}>{title}</h1>
1376					{parts && (
1377						<p className={heroSubtitle}>
1378							{parts.text}
1379							{parts.emojis && <span className={heroSubtitleEmojis}>{parts.emojis}</span>}
1380						</p>
1381					)}
1382				</div>
1383			</section>
