				<div className={globalBackground} aria-hidden="true" />
				{showShader && (
					<Suspense fallback={null}>
						<WaterShader />
					</Suspense>
				)}
				<a
					href="#app-root"
					aria-label="Skip to main content"
					style={{
						position: 'absolute',
						left: '-999px',
						top: '-999px',
