					}}
					onBlur={(e) => {
						e.currentTarget.style.left = '-999px';
						e.currentTarget.style.top = '-999px';
					}}
				>
					Skip to content
				</a>
				<ErrorBoundary>
					<Header />
					<main id="app-root" className={contentLayer}>
						<Outlet />
					</main>
					<Footer />
