										style={{
											position: 'fixed',
											bottom: '10px',
											left: '10px',
											background: 'rgba(255,165,0,0.65)',
											color: '#111',
											padding: '8px 12px',
											borderRadius: '6px',
											fontSize: '12px',
											fontWeight: '600',
											zIndex: 999999,
											boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
											backdropFilter: 'blur(6px)',
